Here's an idiomatic Pulumi TypeScript implementation.

## `serviceStack.ts` — the ComponentResource

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ServiceStackArgs {
    /** "dev" | "prod" — usually pulumi.getStack() */
    environment: string;
    /** RDS instance class, e.g. db.t3.micro / db.t3.medium */
    dbInstanceClass: string;
    /** Multi-AZ for prod, single-AZ for dev */
    dbMultiAz: boolean;
    /** KMS-encrypted storage (prod) vs AES-256 default (dev) */
    dbStorageEncrypted: boolean;
    /** Master DB password — supplied as a Pulumi secret */
    dbPassword: pulumi.Input<string>;
    /** Subnet group the RDS instance lives in (private subnets) */
    dbSubnetGroupName: pulumi.Input<string>;
    /** Security groups controlling DB ingress */
    dbSecurityGroupIds: pulumi.Input<string>[];
    /** OIDC provider ARN for the EKS cluster (IRSA trust) */
    oidcProviderArn: pulumi.Input<string>;
    /** OIDC provider URL (without https://) */
    oidcProviderUrl: pulumi.Input<string>;
    /** k8s service account, e.g. "app:web" (namespace:name) */
    serviceAccount: string;
    tags?: { [k: string]: string };
}

export class ServiceStack extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly roleArn: pulumi.Output<string>;
    /** DB connection string — marked secret */
    public readonly connectionString: pulumi.Output<string>;

    constructor(
        name: string,
        args: ServiceStackArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("app:infra:ServiceStack", name, {}, opts);

        const isProd = args.environment === "prod";
        const tags = { Environment: args.environment, ...(args.tags ?? {}) };
        const childOpts = { parent: this };

        // ---------------------------------------------------------------
        // 1. S3 bucket — versioned, encrypted, private
        // ---------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(
            `${name}-assets`,
            { tags },
            childOpts,
        );

        new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: bucket.id,
                versioningConfiguration: { status: "Enabled" },
            },
            childOpts,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-sse`,
            {
                bucket: bucket.id,
                rules: [
                    {
                        applyServerSideEncryptionByDefault: {
                            // prod → KMS, dev → AES256
                            sseAlgorithm: isProd ? "aws:kms" : "AES256",
                        },
                        bucketKeyEnabled: isProd,
                    },
                ],
            },
            childOpts,
        );

        // Block ALL public access (AC #1)
        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-pab`,
            {
                bucket: bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            childOpts,
        );

        // ---------------------------------------------------------------
        // 2. RDS PostgreSQL — deletion protection, private, 7d+ backups
        // ---------------------------------------------------------------
        const db = new aws.rds.Instance(
            `${name}-postgres`,
            {
                engine: "postgres",
                engineVersion: "16.3",
                instanceClass: args.dbInstanceClass,
                allocatedStorage: 20,
                maxAllocatedStorage: isProd ? 200 : 50,

                dbName: "appdb",
                username: "appadmin",
                password: args.dbPassword,

                dbSubnetGroupName: args.dbSubnetGroupName,
                vpcSecurityGroupIds: args.dbSecurityGroupIds,

                // AC #2
                deletionProtection: true,
                backupRetentionPeriod: isProd ? 30 : 7,
                publiclyAccessible: false,

                multiAz: args.dbMultiAz,
                storageEncrypted: args.dbStorageEncrypted,

                skipFinalSnapshot: !isProd,
                finalSnapshotIdentifier: isProd
                    ? `${name}-final-snapshot`
                    : undefined,
                applyImmediately: !isProd,

                tags,
            },
            childOpts,
        );

        // ---------------------------------------------------------------
        // 3. IAM role for service account (IRSA / OIDC trust)
        // ---------------------------------------------------------------
        const assumeRolePolicy = pulumi
            .all([args.oidcProviderArn, args.oidcProviderUrl])
            .apply(([arn, url]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Effect: "Allow",
                            Principal: { Federated: arn },
                            Action: "sts:AssumeRoleWithWebIdentity",
                            Condition: {
                                StringEquals: {
                                    [`${url}:aud`]: "sts.amazonaws.com",
                                    [`${url}:sub`]: `system:serviceaccount:${args.serviceAccount.replace(
                                        ":",
                                        ":",
                                    )}`,
                                },
                            },
                        },
                    ],
                }),
            );

        const role = new aws.iam.Role(
            `${name}-sa-role`,
            { assumeRolePolicy, tags },
            childOpts,
        );

        // Least-privilege inline policy (AC #4 — no wildcard actions).
        const policyDoc = pulumi
            .all([bucket.arn])
            .apply(([bArn]) =>
                JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [
                        {
                            Sid: "S3ObjectAccess",
                            Effect: "Allow",
                            Action: [
                                "s3:GetObject",
                                "s3:PutObject",
                                "s3:DeleteObject",
                            ],
                            Resource: `${bArn}/*`,
                        },
                        {
                            Sid: "S3ListBucket",
                            Effect: "Allow",
                            Action: ["s3:ListBucket"],
                            Resource: bArn,
                        },
                    ],
                }),
            );

        new aws.iam.RolePolicy(
            `${name}-sa-policy`,
            { role: role.id, policy: policyDoc },
            childOpts,
        );

        // ---------------------------------------------------------------
        // Outputs
        // ---------------------------------------------------------------
        this.bucketName = bucket.id;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.endpoint;
        this.roleArn = role.arn;

        this.connectionString = pulumi.secret(
            pulumi.interpolate`postgresql://appadmin:${args.dbPassword}@${db.endpoint}/appdb`,
        );

        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            dbEndpoint: this.dbEndpoint,
            roleArn: this.roleArn,
            connectionString: this.connectionString,
        });
    }
}
```

## `index.ts` — wiring config → component

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ServiceStack } from "./serviceStack";

const config = new pulumi.Config();
const stack = pulumi.getStack(); // "dev" | "prod"

// dbPassword read as a Pulumi secret (encrypted at rest in the stack config)
const dbPassword = config.requireSecret("dbPassword");

const svc = new ServiceStack("app", {
    environment: stack,
    dbInstanceClass: config.require("dbInstanceClass"),
    dbMultiAz: config.requireBoolean("dbMultiAz"),
    dbStorageEncrypted: config.requireBoolean("dbStorageEncrypted"),
    dbPassword,
    dbSubnetGroupName: config.require("dbSubnetGroupName"),
    dbSecurityGroupIds: config.requireObject<string[]>("dbSecurityGroupIds"),
    oidcProviderArn: config.require("oidcProviderArn"),
    oidcProviderUrl: config.require("oidcProviderUrl"),
    serviceAccount: config.require("serviceAccount"),
});

export const bucketName = svc.bucketName;
export const dbEndpoint = svc.dbEndpoint;
export const roleArn = svc.roleArn;
export const connectionString = svc.connectionString; // secret
```

## `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  app:dbInstanceClass: db.t3.micro
  app:dbMultiAz: "false"
  app:dbStorageEncrypted: "false"
  app:dbSubnetGroupName: dev-db-subnets
  app:dbSecurityGroupIds:
    - sg-0dev0000000000000
  app:oidcProviderArn: arn:aws:iam::111111111111:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/DEV
  app:oidcProviderUrl: oidc.eks.us-east-1.amazonaws.com/id/DEV
  app:serviceAccount: "app:web"
  app:dbPassword:
    secure: AAABANd...   # set via: pulumi config set --secret app:dbPassword <value>
```

## `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  app:dbInstanceClass: db.t3.medium
  app:dbMultiAz: "true"
  app:dbStorageEncrypted: "true"
  app:dbSubnetGroupName: prod-db-subnets
  app:dbSecurityGroupIds:
    - sg-0prod000000000000
  app:oidcProviderArn: arn:aws:iam::222222222222:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/PROD
  app:oidcProviderUrl: oidc.eks.us-east-1.amazonaws.com/id/PROD
  app:serviceAccount: "app:web"
  app:dbPassword:
    secure: AAABANm...   # pulumi config set --secret app:dbPassword <value>
```

## How the acceptance criteria are met

| Criterion | Where |
|---|---|
| **Bucket versioning + encryption + no public access** | `BucketVersioningV2`, `BucketServerSideEncryptionConfigurationV2` (AES256 dev / KMS prod), `BucketPublicAccessBlock` all-true |
| **RDS deletion protection, backups ≥7d, not public** | `deletionProtection: true`, `backupRetentionPeriod` 7 (dev) / 30 (prod), `publiclyAccessible: false` |
| **Secret never in plaintext** | `config.requireSecret` + `pulumi.secret(...)`; stored `secure:` (encrypted) in stack yaml |
| **IAM least privilege** | Scoped S3 actions on bucket ARN only; OIDC-trusted assume-role; no wildcards |
| **Environment isolation** | Separate `dev`/`prod` stacks → independent state, independently deployable |

**Usage:**

```bash
pulumi stack init dev
pulumi config set --secret app:dbPassword 'S0meStrongPass'
pulumi up

pulumi stack init prod
pulumi config set --secret app:dbPassword 'AnotherStrongPass'
pulumi up
```

Note: this component scopes to bucket + RDS + IAM as requested. The EKS cluster, CloudFront/ACM, and cross-region replication from the broader spine would be added as sibling components consuming the same stack config, keeping each concern independently testable.
